import { useMemo, useState, useEffect } from 'react';
import { debounce } from './throttle';
/**
 * Sometimes the neon components can fire off a lot of events like when a user is typing in a NeonTextField.
 * This function allows the user types for a bit and then stop, for a specified number of milliseconds. The React
 * state will only be set AFTER the user stops typing.
 * @param defaultValue Just like the default value in useState
 * @param debounceTime The number of milliseconds to wait for the setter to stop being called before actually setting the React state.
 * @returns [stateVariable (just like React), debouncedSetterFunction(value, callback), setterFunction (Just like in React)]
 *
 * @example const [searchString, setSearchStringDebounced] = useStateDebounced<string>('', 400);
 * <NeonTextField modelValue={searchString} modelValueChanged={(value: string | undefined): void => { setSearchStringDebounced(value || '', (): void => {
 *    console.log('The user stopped typing. Time to make the network call');
 * }) }}
 */
export function useStateDebounced(defaultValue, debounceTime) {
    const [value, setValue] = useState(defaultValue);
    const setValueDebounce = useMemo(() => {
        return debounce((v, callback) => {
            setValue(v);
            if (typeof callback === 'function') {
                callback(v);
            }
        }, debounceTime);
    }, [setValue]);
    return [value, setValueDebounce, setValue];
}
/**
 * If you need to run a callback in your react component when the screen size gets changed to above or below
 * a specific breakpoint then this is your function!
 * @param mobileBreakpoint The breakpoint in pixels that you care about.
 * @param callback Gets called when the the screen size changes to be larger than the breakpoint, or the screen
 * size changes to be smaller than the breakpoint.
 */
export function useMobileBreakPointResizeListener(mobileBreakpoint, callback) {
    useEffect(() => {
        //Initialize the 'lastWidth' to the current screen width.
        let lastWidth = window.innerWidth;
        function windowResized() {
            if (window.innerWidth > mobileBreakpoint && lastWidth <= mobileBreakpoint) {
                callback(true);
            }
            if (window.innerWidth <= mobileBreakpoint && lastWidth > mobileBreakpoint) {
                callback(false);
            }
            lastWidth = window.innerWidth;
        }
        //Add the resize listener
        window.addEventListener('resize', windowResized);
        return () => {
            //Remove listener
            window.removeEventListener('resize', windowResized);
        };
    }, []);
}
